<?php require_once __DIR__.'/../config/conexao.php'; require_once __DIR__.'/../includes/funcoes.php'; exigirLogin();$st=$pdo->prepare('SELECT id,total,metodo_pagamento,status,criado_em FROM pedidos WHERE usuario_id=? ORDER BY criado_em DESC');$st->execute([$_SESSION['usuario_id']]);$pedidos=$st->fetchAll();$limparCarrinho=!empty($_SESSION['limpar_carrinho']);unset($_SESSION['limpar_carrinho']); ?>
<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Minha conta | Doppio Mocha</title><link rel="stylesheet" href="../css/code.css"></head><body><?php require __DIR__.'/../includes/cabecalho.php'; ?><main class="secao-produtos"><div class="titulo-secao"><div><span class="subtitulo-secao">ÁREA DO CLIENTE</span><h2>Olá, <?= h($_SESSION['usuario_nome']??'cliente') ?>!</h2></div><a href="../auth/sair.php">Sair da conta</a></div><h3 class="titulo-pedidos">Meus pedidos</h3><?php if(!$pedidos): ?><p class="mensagem-vazia">Você ainda não realizou pedidos. <a href="produtos.php">Conheça nosso cardápio.</a></p><?php else: ?><div class="tabela-responsiva"><table class="tabela-pedidos"><thead><tr><th>Pedido</th><th>Data</th><th>Pagamento</th><th>Status</th><th>Total</th></tr></thead><tbody><?php foreach($pedidos as $p): ?><tr><td>#<?= (int)$p['id'] ?></td><td><?= date('d/m/Y H:i',strtotime($p['criado_em'])) ?></td><td><?= h(strtoupper($p['metodo_pagamento'])) ?></td><td><?= h(str_replace('_',' ',$p['status'])) ?></td><td><?= moeda((float)$p['total']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></main><?php require __DIR__.'/../includes/rodape.php'; ?><?php if($limparCarrinho): ?><script>localStorage.removeItem('doppio-carrinho');</script><?php endif; ?></body></html>
